
.shell {
  position: relative;
  overflow: hidden;
  width: 100%;
  max-width: 860px;
  margin: 0 auto;
  padding: 18px;
  border: 1px solid var(--line-strong);
  border-radius: 26px;
  background:
    radial-gradient(circle at top right, rgba(238, 139, 154, 0.12), transparent 34%),
    radial-gradient(circle at 15% 15%, rgba(141, 199, 217, 0.28), transparent 26%),
    linear-gradient(180deg, rgba(13, 20, 31, 0.96), rgba(19, 28, 42, 0.96));
  color: var(--ink-main);
  box-shadow:
    0 24px 70px rgba(0, 0, 0, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
  font-family: var(--font-body);
}
.shell::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 20% 10%, rgba(255, 255, 255, 0.08), transparent 10%),
    radial-gradient(circle at 50% 16%, rgba(255, 255, 255, 0.05), transparent 7%),
    linear-gradient(120deg, transparent 0 25%, rgba(255, 255, 255, 0.04) 25% 27%, transparent 27% 52%, rgba(255, 255, 255, 0.03) 52% 54%, transparent 54% 100%);
  pointer-events: none;
}
.mist {
  position: absolute;
  inset: auto -10% -35% auto;
  width: 320px;
  height: 320px;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.18), transparent 68%);
  filter: blur(10px);
  pointer-events: none;
}
.hero {
  position: relative;
  display: grid;
  grid-template-columns: 1.4fr 0.9fr;
  gap: 16px;
  margin-bottom: 16px;
}
.hero-copy,
.affection-card,
.info-card,
.main-panel,
.side-panel {
  position: relative;
  z-index: 1;
  border: 1px solid var(--line-soft);
  background: var(--bg-soft);
  backdrop-filter: blur(6px);
}
.hero-copy {
  padding: 18px 18px 16px;
  border-radius: 22px;
}
.eyebrow {
  color: var(--accent-water);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  font-size: 0.75rem;
  margin-bottom: 8px;
}
.hero-copy h1 {
  font-family: var(--font-title);
  font-size: clamp(2rem, 5vw, 2.9rem);
  line-height: 1;
  margin-bottom: 8px;
}
.subtitle {
  color: var(--accent-gold);
  font-size: 0.95rem;
  margin-bottom: 12px;
}
.quote {
  color: var(--ink-soft);
  line-height: 1.7;
}
.affection-card {
  border-radius: 22px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 10px;
}
.affection-head,
.affection-foot,
.summary-line,
.collection-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.affection-head strong {
  color: var(--accent-eye);
  font-size: 1.8rem;
  font-family: var(--font-title);
}
.meter {
  height: 12px;
  border-radius: 999px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.08);
}
.meter-fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--accent-water), var(--accent-eye));
  box-shadow: 0 0 18px rgba(238, 139, 154, 0.45);
}
.affection-foot {
  color: var(--ink-soft);
  font-size: 0.86rem;
}
.quick-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 14px;
}
.info-card,
.main-panel,
.side-panel {
  border-radius: 18px;
}
.info-card {
  padding: 14px;
}
.label,
.detail-label {
  display: block;
  color: var(--ink-faint);
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 6px;
}
.info-card strong,
.summary-line strong {
  display: block;
  color: var(--accent-scale);
  margin-bottom: 5px;
}
.info-card p,
.body-copy,
.detail-box p,
.habit-item p,
.collection-item p {
  color: var(--ink-soft);
  line-height: 1.65;
}
.panel-switch {
  display: flex;
  gap: 8px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}
.panel-btn {
  border: 1px solid var(--line-soft);
  border-radius: 999px;
  padding: 8px 14px;
  background: rgba(255, 255, 255, 0.03);
  color: var(--ink-soft);
  cursor: pointer;
  transition:
    transform 0.18s ease,
    background 0.18s ease,
    color 0.18s ease,
    border-color 0.18s ease;
}
.panel-btn.active {
  color: var(--bg-deep);
  background: linear-gradient(90deg, var(--accent-scale), var(--accent-water));
  border-color: transparent;
}
.panel-btn:hover {
  transform: translateY(-1px);
}
.content-grid {
  display: grid;
  grid-template-columns: 1.5fr 0.8fr;
  gap: 12px;
}
.main-panel,
.side-panel {
  padding: 16px;
}
.section-title {
  font-family: var(--font-title);
  font-size: 1.15rem;
  margin-bottom: 12px;
  color: var(--accent-scale);
}
.tag-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}
.tag {
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  color: var(--accent-water);
  font-size: 0.82rem;
}
.detail-box,
.habit-item,
.collection-item,
.empty-box {
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.03);
  border-radius: 14px;
}
.detail-box {
  margin-top: 12px;
  padding: 12px;
}
.habit-list,
.collection-list {
  display: grid;
  gap: 10px;
}
.habit-item,
.collection-item,
.empty-box {
  padding: 12px;
}
.habit-item span {
  display: inline-block;
  margin-bottom: 6px;
  color: var(--accent-gold);
}
.collection-head span {
  color: var(--ink-faint);
  font-size: 0.8rem;
}
.summary-line {
  padding: 10px 0;
  border-bottom: 1px dashed rgba(255, 255, 255, 0.09);
}
.summary-line:last-child {
  border-bottom: 0;
}
.phase-cold {
  --accent-water: #8ca4b7;
  --accent-eye: #d88492;
}
.phase-watch {
  --accent-water: #90c2d0;
  --accent-eye: #ea9198;
}
.phase-soft {
  --accent-water: #8fd3da;
  --accent-eye: #f1a3ae;
}
.phase-wrap {
  --accent-water: #9fdae2;
  --accent-eye: #f39ba6;
}
.phase-nest {
  --accent-water: #b3e0df;
  --accent-eye: #ffb0b4;
}
@media (max-width: 900px) {
  .quick-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .content-grid {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 640px) {
  .shell {
    padding: 14px;
    border-radius: 20px;
  }
  .hero {
    grid-template-columns: 1fr;
  }
  .quick-grid {
    grid-template-columns: 1fr;
  }
  .affection-head strong {
    font-size: 1.55rem;
  }
}
